#let diagram = cetz.canvas({
  import cetz.draw: *

  let oy  = 2.8      // height of hinge O
  let xe  = 5.2      // rod length (2L in the problem)
  let mx  = xe / 2   // midpoint M at L from O
  let yy  = oy + mx  // OY = L so string is at 45 deg
  let cx  = xe / 3   // centre of gravity C at L/3 from O

  // --- Wall ---
  line((0, -0.2), (0, yy + 0.6), stroke: 2pt + black)
  for i in range(14) {
    let y = i * 0.48 - 0.2
    line((0, y), (-0.32, y + 0.32), stroke: 0.9pt + luma(60%))
  }

  // --- Hinge O ---
  circle((0, oy), radius: 0.1, fill: black)
  content((-0.55, oy), anchor: "east", text(size: 16pt)[$O$])

  // --- Point Y on wall ---
  circle((0, yy), radius: 0.1, fill: black)
  content((-0.55, yy), anchor: "east", text(size: 16pt)[$Y$])

  // --- Rod OX ---
  line((0, oy), (xe, oy), stroke: 2.8pt + black)
  circle((xe, oy), radius: 0.1, fill: black)
  content((xe + 0.25, oy), anchor: "west", text(size: 16pt)[$X$])

  // --- Label: 2L (total rod length) ---
  content((xe / 2, oy - 0.35), text(size: 13pt)[$2L$])

  // --- Midpoint M (string attachment) ---
  circle((mx, oy), radius: 0.12, fill: black)
  content((mx, oy + 0.42), text(size: 15pt)[$M$])

  // --- Label: L (from O to M) ---
  content((mx / 2, oy + 0.35), text(size: 13pt)[$L$])

  // --- Centre of gravity C (plain black tick below rod) ---
  circle((cx, oy), radius: 0.12, fill: black)
  content((cx, oy - 0.48), text(size: 15pt)[$C$])

  // --- Label: L/3 from O to C ---
  content((cx / 2, oy - 0.48), text(size: 13pt)[$L\/3$])

  // --- String MY (plain black) ---
  line((mx, oy), (0, yy), stroke: (thickness: 1.6pt, paint: black, dash: "dashed"))

  // --- Label: 45° angle ---
  content((mx * 0.6, oy + 0.35), text(size: 14pt)[$45 degree$])

  // --- Weight W hanging from X ---
  line((xe, oy), (xe, 0.82), stroke: 1.3pt + black)
  rect((xe - 0.32, 0.22), (xe + 0.32, 0.82), fill: luma(40%), stroke: 1.8pt)
  content((xe, -0.12), text(size: 15pt)[$W$])

  // --- Label: 3W (rod weight at C) ---
  content((cx + 0.65, oy - 0.48), text(size: 14pt)[$3W$])

  // --- Four candidate reaction directions from O ---
  let ray(dx, dy, lbl, lx, ly) = {
    let rlen = 1.9
    let n = calc.sqrt(dx * dx + dy * dy)
    let ex = dx / n * rlen
    let ey = dy / n * rlen
    line((0, oy), (ex, oy + ey), mark: (end: ">"),
      stroke: (paint: rgb("#c0392b"), thickness: 1.6pt, dash: "dashed"))
    content((lx, ly), text(size: 16pt, fill: rgb("#c0392b"))[#lbl])
  }

  // P: along rod   Q: down-right (trap)   R: up-right (correct)   S: straight down
  ray(1,  0, "P",  2.2,  oy - 0.28)
  ray(2, -1, "Q",  2.05, oy - 1.1)
  ray(3,  1, "R",  2.1,  oy + 0.85)
  ray(0, -1, "S",  0.35, oy - 2.05)
})

